function selectClub(i){if(flight||charging||complete)return;club=i;buildAim();updateUI();}
function targetDistance(){let lie=terrain(ballPos.x,ballPos.z);return clubs[club][2]*power*(lie==='rough'?.83:lie==='bunker'?(club===4?.85:.5):1);}
