function updateUI(){const h=holes[holeIndex],distance=ballPos.distanceTo(pin),near=personPos.distanceTo(ballPos)<8,lie=terrain(ballPos.x,ballPos.z);$('hole').textContent=String(holeIndex+1).padStart(2,'0');$('par').textContent=h.par;$('hole-name').textContent=h.name;$('distance').innerHTML=Math.round(distance)+' <small>yd</small>';$('stroke').textContent=complete?strokes:strokes+1;const total=scores.reduce((sum,n,i)=>sum+n-holes[i].par,0);$('score').textContent=total===0?'E':total>0?'+'+total:total;$('club-name').textContent=clubs[club][0];$('carry').textContent=clubs[club][2];document.querySelectorAll('[data-club]').forEach(b=>b.classList.toggle('selected',+b.dataset.club===club));$('aim-deg').textContent=Math.round(aim*180/Math.PI)+'°';$('power-text').textContent=Math.round(power*100)+'%';$('power-fill').style.width=power*100+'%';$('mode-label').textContent=inCart?'TAKING THE SCENIC ROUTE':flight?'BALL IN FLIGHT':near?'READY TO PLAY':'EXPLORE THE COURSE';$('mode-text').textContent=inCart?Math.round(Math.abs(speed)*2.2)+' mph · Golf cart':flight?'Follow your shot':near?lie.charAt(0).toUpperCase()+lie.slice(1)+' lie':Math.round(personPos.distanceTo(ballPos))+' yd to your ball';$('mode-icon').textContent=inCart?'▰':'⚑';$('cart-button').innerHTML=inCart?'Exit cart <kbd>E</kbd>':'Drive cart <kbd>E</kbd>';$('swing').disabled=inCart||flight!==null||!near||complete;$('marker').style.display=flight||complete?'none':'block';$('shot-card').style.opacity=inCart?'.55':'1';document.querySelector('.map-card .eyebrow span').textContent=String(holeIndex+1).padStart(2,'0')+' / 03';}
